def apply_op(op, a, b):
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if op == '/':
        return a / b
    raise ValueError(op)

def evaluate(expr):
    stack = []
    for tok in expr.split():
        print(f'Processing token: {tok}, stack before: {stack}')
        if tok in ('+', '-', '*', '/'):
            print(f'  Popping b: {stack.pop()}')
            b = stack.pop()
            print(f'  Popping a: {stack.pop()}')
            a = stack.pop()
            result = apply_op(tok, a, b)
            print(f'  Applying {tok}({a}, {b}) = {result}')
            stack.append(result)
        else:
            stack.append(float(tok))
            print(f'  Pushed {float(tok)}, stack is now {stack}')
    return stack[0]

print('Result:', evaluate('10 4 -'))
